package Google::Cloud::Developerconnect::V1::DeveloperConnect::DeveloperConnectClient;

=pod

=head2 Service Client: Google::Cloud::Developerconnect::V1::DeveloperConnect::DeveloperConnectClient

Client stub representing the remote C<DeveloperConnect> gRPC service. Delegates call dispatching to L<Google::gRPC::Client>.

=head3 target

The endpoint target address. Defaults to C<developerconnect.googleapis.com:443>.

=head3 credentials

The authentication credentials provider. Defaults to application default credentials via L<Google::Auth>.

=cut

use Moo;
use Google::Auth;
use Google::gRPC::Client;

has credentials => ( is => 'ro', default => sub { Google::Auth->default() } );
has target      => ( is => 'ro', default => 'developerconnect.googleapis.com:443' );

has _grpc_client => (
    is => 'ro',
    lazy => 1,
    builder => sub {
        my $self = shift;
        return Google::gRPC::Client->new(
            target     => $self->target,
            auth_token => $self->credentials->get_token(),
        );
    }
);

sub list_connections {
    my ($self, $args) = @_;
    my $req = ref($args) eq 'HASH'
        ? Google::Cloud::Developerconnect::V1::DeveloperConnect::ListConnectionsRequest->new($args)
        : $args;
    return $self->_grpc_client->call({
        service        => 'google.cloud.developerconnect.v1.DeveloperConnect',
