=head2 Google::Cloud::Developerconnect::V1::DeveloperConnect::CreateConnectionRequest

Message for creating a Connection

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->parent() >> / C<< $msg->parent($value) >>

Type: C<String>

Required. Value for parent.

=item * C<< $msg->connection_id() >> / C<< $msg->connection_id($value) >>

Type: C<String>

Required. Id of the requesting object
If auto-generating Id server-side, remove this field and
connection_id from the method_signature of Create RPC

=item * C<< $msg->connection() >> / C<< $msg->connection($value) >>

Type: C<Message> (L<Google::Cloud::Developerconnect::V1::DeveloperConnect::Connection>)

Required. The resource being created

=item * C<< $msg->request_id() >> / C<< $msg->request_id($value) >>

Type: C<String>

Optional. An optional request ID to identify requests. Specify a unique
request ID so that if you must retry your request, the server will know to
ignore the request if it has already been completed. The server will
guarantee that for at least 60 minutes since the first request.

For example, consider a situation where you make an initial request and the
request times out. If you make the request again with the same request
ID, the server can check if original operation with the same request ID
was received, and if so, will ignore the second request. This prevents
clients from accidentally creating duplicate commitments.

The request ID must be a valid UUID with the exception that zero UUID is
not supported (00000000-0000-0000-0000-000000000000).

=item * C<< $msg->validate_only() >> / C<< $msg->validate_only($value) >>

Type: C<Bool>

Optional. If set, validate the request, but do not actually post it.

=back

=head2 Google::Cloud::Developerconnect::V1::DeveloperConnect::UpdateConnectionRequest

Message for updating a Connection

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->update_mask() >> / C<< $msg->update_mask($value) >>

Type: C<Message> (L<Google::Protobuf::FieldMask::FieldMask>)

Required. Field mask is used to specify the fields to be overwritten in the
Connection resource by the update.
The fields specified in the update_mask are relative to the resource, not
the full request. A field will be overwritten if it is in the mask. If the
user does not provide a mask then all fields will be overwritten.

=item * C<< $msg->connection() >> / C<< $msg->connection($value) >>

Type: C<Message> (L<Google::Cloud::Developerconnect::V1::DeveloperConnect::Connection>)

Required. The resource being updated

=item * C<< $msg->request_id() >> / C<< $msg->request_id($value) >>

Type: C<String>

Optional. An optional request ID to identify requests. Specify a unique
request ID so that if you must retry your request, the server will know to
ignore the request if it has already been completed. The server will
guarantee that for at least 60 minutes since the first request.

For example, consider a situation where you make an initial request and the
request times out. If you make the request again with the same request
ID, the server can check if original operation with the same request ID
was received, and if so, will ignore the second request. This prevents
clients from accidentally creating duplicate commitments.

The request ID must be a valid UUID with the exception that zero UUID is
not supported (00000000-0000-0000-0000-000000000000).

=item * C<< $msg->allow_missing() >> / C<< $msg->allow_missing($value) >>

Type: C<Bool>

Optional. If set to true, and the connection is not found a new connection
will be created. In this situation `update_mask` is ignored.
The creation will succeed only if the input connection has all the
necessary information (e.g a github_config with both  user_oauth_token and
installation_id properties).

=item * C<< $msg->validate_only() >> / C<< $msg->validate_only($value) >>

Type: C<Bool>

Optional. If set, validate the request, but do not actually post it.

=back

