=item * C<< $msg->files() >> / C<< $msg->files($value) >>

Type: C<Message> (L<Google::Cloud::Developerconnect::V1::DeveloperConnect::FileDiff>)

List of file changes and patch diffs. Omitted when view is `BASIC`.
Patch diffs (`FileDiff.patch`) are only populated when `path_filters` is
specified in the request.

=back

=head2 Google::Cloud::Developerconnect::V1::DeveloperConnect::FetchGitRepositoryLinkCommitListRequest

