Type: C<Message> (L<Google::Cloud::Developerconnect::V1::DeveloperConnect::PullRequest>)

The list of Pull Requests.

=item * C<< $msg->next_page_token() >> / C<< $msg->next_page_token($value) >>

Type: C<String>

A token, which can be sent as `page_token` to retrieve the next page.
If this field is omitted, there are no subsequent pages.

=back

=head2 Google::Cloud::Developerconnect::V1::DeveloperConnect::AccountConnector

AccountConnector encapsulates what a platform administrator needs to
configure for users to connect to the service providers, which includes,
among other fields, the OAuth client ID, client secret, and authorization and
token endpoints.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->provider_oauth_config() >> / C<< $msg->provider_oauth_config($value) >>

Type: C<Message> (L<Google::Cloud::Developerconnect::V1::DeveloperConnect::ProviderOAuthConfig>)

Optional. Provider OAuth config.

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Identifier. The resource name of the accountConnector, in the format
`projects/{project}/locations/{location}/accountConnectors/{account_connector_id}`.

=item * C<< $msg->create_time() >> / C<< $msg->create_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The timestamp when the accountConnector was created.

=item * C<< $msg->update_time() >> / C<< $msg->update_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The timestamp when the accountConnector was updated.

=item * C<< $msg->annotations() >> / C<< $msg->annotations($value) >>

Type: C<Message> (L<Google::Cloud::Developerconnect::V1::DeveloperConnect::AccountConnector::AnnotationsEntry>)

Optional. Allows users to store small amounts of arbitrary data.

=item * C<< $msg->etag() >> / C<< $msg->etag($value) >>

Type: C<String>

Optional. This checksum is computed by the server based on the value of
other fields, and may be sent on update and delete requests to ensure the
client has an up-to-date value before proceeding.

=item * C<< $msg->labels() >> / C<< $msg->labels($value) >>

Type: C<Message> (L<Google::Cloud::Developerconnect::V1::DeveloperConnect::AccountConnector::LabelsEntry>)

Optional. Labels as key value pairs

=item * C<< $msg->oauth_start_uri() >> / C<< $msg->oauth_start_uri($value) >>

Type: C<String>

Output only. Start OAuth flow by clicking on this URL.

=back

=head2 Google::Cloud::Developerconnect::V1::DeveloperConnect::User

User represents a user connected to the service providers through
a AccountConnector.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Identifier. Resource name of the user, in the format
`projects/*/locations/*/accountConnectors/*/users/*`.

=item * C<< $msg->display_name() >> / C<< $msg->display_name($value) >>

Type: C<String>

Output only. Developer Connect automatically converts user identity
to some human readable description, e.g., email address.

=item * C<< $msg->create_time() >> / C<< $msg->create_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The timestamp when the user was created.

=item * C<< $msg->last_token_request_time() >> / C<< $msg->last_token_request_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The timestamp when the token was last requested.

=back

=head2 Google::Cloud::Developerconnect::V1::DeveloperConnect::ProviderOAuthConfig

ProviderOAuthConfig is the OAuth config for a provider.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->system_provider_id() >> / C<< $msg->system_provider_id($value) >>

Type: C<Enum> (L<Google::Cloud::Developerconnect::V1::SystemProvider>)

Optional. Immutable. Developer Connect provided OAuth.

=item * C<< $msg->scopes() >> / C<< $msg->scopes($value) >>

Type: C<String>

Required. User selected scopes to apply to the Oauth config
In the event of changing scopes, user records under AccountConnector will
be deleted and users will re-auth again.

=back

